import{_ as a,o as s,c as n,a3 as t}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Module Dependencies","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Module Dependencies | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/architecture/module-dependencies"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Module Dependencies | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/architecture/module-dependencies"}]]},"headers":[],"relativePath":"architecture/module-dependencies.md","filePath":"architecture/module-dependencies.md","lastUpdated":1788177646000}'),o={name:"architecture/module-dependencies.md"};function i(d,e,r,p,l,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="module-dependencies" tabindex="-1">Module Dependencies <a class="header-anchor" href="#module-dependencies" aria-label="Permalink to &quot;Module Dependencies&quot;">​</a></h1><p>Modules may depend on other modules.</p><p>This document defines how dependency relationships are described for product design and implementation. Runtime enforcement is implemented via <code>module_dependencies</code>, <code>ModuleDependencyResolver</code>, and <code>ModuleSubscriptionService</code> (install blocks when required dependencies are missing).</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Dependencies should be categorized as:</p><table tabindex="0"><thead><tr><th>Category</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Required</strong></td><td>The dependent module cannot function correctly without the dependency installed and available</td></tr><tr><td><strong>Optional</strong></td><td>The dependent module works alone; the dependency unlocks extra integrations or features</td></tr></tbody></table><h2 id="commercial-nature-of-a-dependency" tabindex="-1">Commercial nature of a dependency <a class="header-anchor" href="#commercial-nature-of-a-dependency" aria-label="Permalink to &quot;Commercial nature of a dependency&quot;">​</a></h2><p>Independently of required vs optional, a dependency relationship may be:</p><table tabindex="0"><thead><tr><th>Nature</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Free</strong></td><td>The dependency module is free (or included) for the workspace</td></tr><tr><td><strong>Billable</strong></td><td>The dependency module is (or may become) a paid marketplace module</td></tr></tbody></table><p>A required dependency can be free or billable. An optional dependency can be free or billable. Licensing of each module remains independent — see <a href="./module-licensing">Module Licensing</a>.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>These examples illustrate the intended design language. They are not a commitment that every example is already implemented.</p><h3 id="meetings-→-calendar-required" tabindex="-1">Meetings → Calendar (required) <a class="header-anchor" href="#meetings-→-calendar-required" aria-label="Permalink to &quot;Meetings → Calendar (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Meetings</span></span>
<span class="line"><span>  └── depends on Calendar   (required)</span></span></code></pre></div><p>Meeting scheduling assumes calendar concepts (availability, time ranges, calendar views). Meetings should declare Calendar as a <strong>required</strong> dependency.</p><p><strong>Status:</strong> <a href="/user-guide/calendar-overview">Calendar</a> and <a href="/user-guide/meetings-overview">Meetings</a> are shipped. Meetings projects onto <code>CalendarEvent</code> via <code>CalendarEventService::upsertFromSource</code> (<code>source=meeting</code>, morph alias <code>meeting</code>).</p><h3 id="leads-→-contacts-optional" tabindex="-1">Leads → Contacts (optional) <a class="header-anchor" href="#leads-→-contacts-optional" aria-label="Permalink to &quot;Leads → Contacts (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leads</span></span>
<span class="line"><span>  └── may depend on Contacts   (optional — unlocks full lead convert)</span></span></code></pre></div><p>Leads works without Contacts. When Contacts is entitled, <code>POST /leads/{id}/convert</code> creates (or links) a Contact and sets <code>leads.contact_id</code>. Without Contacts, convert remains the status-oriented placeholder (<code>conversion_meta.stub = true</code>).</p><p><strong>Status:</strong> <a href="/user-guide/contacts-overview">Contacts</a> is shipped. No hard <code>module_dependencies</code> row — soft entitlement check in <code>LeadService::convert</code>.</p><h3 id="contacts-→-companies-optional" tabindex="-1">Contacts → Companies (optional) <a class="header-anchor" href="#contacts-→-companies-optional" aria-label="Permalink to &quot;Contacts → Companies (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Contacts</span></span>
<span class="line"><span>  └── may depend on Companies   (optional — unlocks company picker / company_id)</span></span></code></pre></div><p>Contacts works without Companies (legacy free-text <code>company</code> string only). When Companies is entitled, Contact create/update can set <code>company_id</code> and sync the legacy string from the Company name. No hard <code>module_dependencies</code> row — soft entitlement / SPA gating.</p><p><strong>Status:</strong> <a href="/user-guide/companies-overview">Companies</a> is shipped.</p><h3 id="activities-→-contacts-companies-leads-optional" tabindex="-1">Activities → Contacts / Companies / Leads (optional) <a class="header-anchor" href="#activities-→-contacts-companies-leads-optional" aria-label="Permalink to &quot;Activities → Contacts / Companies / Leads (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Activities</span></span>
<span class="line"><span>  ├── may depend on Contacts   (optional — contact_id link)</span></span>
<span class="line"><span>  ├── may depend on Companies  (optional — company_id link)</span></span>
<span class="line"><span>  └── may depend on Leads      (optional — lead_id link)</span></span></code></pre></div><p>Activities works as a licensed module on its own catalog row, but create/update requires at least one related FK. Each FK is validated only when that module is entitled (soft entitlement; no hard <code>module_dependencies</code> row).</p><p><strong>Status:</strong> <a href="/user-guide/activities-overview">Activities</a> is shipped.</p><h3 id="opportunities-→-contacts-companies-leads-optional" tabindex="-1">Opportunities → Contacts / Companies / Leads (optional) <a class="header-anchor" href="#opportunities-→-contacts-companies-leads-optional" aria-label="Permalink to &quot;Opportunities → Contacts / Companies / Leads (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opportunities</span></span>
<span class="line"><span>  ├── may depend on Contacts   (optional — contact_id link)</span></span>
<span class="line"><span>  ├── may depend on Companies  (optional — company_id link)</span></span>
<span class="line"><span>  └── may depend on Leads      (optional — lead_id link)</span></span></code></pre></div><p>Opportunities works as a licensed Sales module on its own catalog row. Related FKs are optional; each is validated only when that module is entitled (soft entitlement; no hard <code>module_dependencies</code> row).</p><p><strong>Sales Pipeline</strong> is not a separate module — stages and the Kanban board live inside Opportunities.</p><p><strong>Status:</strong> <a href="/user-guide/opportunities-overview">Opportunities</a> is shipped.</p><h3 id="quotations-contracts-→-opportunities-required" tabindex="-1">Quotations / Contracts → Opportunities (required) <a class="header-anchor" href="#quotations-contracts-→-opportunities-required" aria-label="Permalink to &quot;Quotations / Contracts → Opportunities (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Quotations</span></span>
<span class="line"><span>  └── depends on Opportunities   (required)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Contracts</span></span>
<span class="line"><span>  └── depends on Opportunities   (required)</span></span></code></pre></div><p>Quotations and Contracts each declare Opportunities as a <strong>required</strong> hard dependency (<code>module_dependencies</code>) — Marketplace install blocks until Opportunities is entitled.</p><p><strong>Status:</strong> <a href="/user-guide/quotations-overview">Quotations</a> and <a href="/user-guide/contracts-overview">Contracts</a> are shipped.</p><h3 id="contracts-→-quotations-optional" tabindex="-1">Contracts → Quotations (optional) <a class="header-anchor" href="#contracts-→-quotations-optional" aria-label="Permalink to &quot;Contracts → Quotations (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Contracts</span></span>
<span class="line"><span>  └── may depend on Quotations   (optional — unlocks quotation_id link)</span></span></code></pre></div><p>Contracts works without Quotations. When Quotations is entitled, a Contract may optionally link <code>quotation_id</code>; validated by <code>LinkableQuotation</code> (soft entitlement + assignee scope). No hard <code>module_dependencies</code> row for this optional link.</p><h3 id="quotations-contracts-→-invoices-optional-shipped-reverse-direction" tabindex="-1">Quotations / Contracts → Invoices (optional, shipped, reverse direction) <a class="header-anchor" href="#quotations-contracts-→-invoices-optional-shipped-reverse-direction" aria-label="Permalink to &quot;Quotations / Contracts → Invoices (optional, shipped, reverse direction)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Quotations</span></span>
<span class="line"><span>  └── may use Invoices   (optional — convert to invoice)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Contracts</span></span>
<span class="line"><span>  └── may use Invoices   (optional — create invoice)</span></span></code></pre></div><p><code>POST /quotations/{id}/convert</code> creates a draft CustomerInvoice from a <code>sent</code>/<code>accepted</code> quotation. <code>POST /contracts/{id}/convert</code> creates a draft CustomerInvoice from an <code>active</code> contract (repeatable). Both are <strong>soft, call-time</strong> entitlement checks inside <code>QuotationService::convertToInvoice()</code> / <code>ContractService::createInvoice()</code> — not <code>module_dependencies</code> rows — so Quotations and Contracts keep working with Invoices uninstalled; only those endpoints 422 until Invoices is installed.</p><p>Quotation convert is one-shot: any invoice with that <code>quotation_id</code> (including from an estimate convert or a contract bill) blocks a second quote convert. Contract billing stays repeatable. Estimate convert is also blocked when the estimate’s quotation is already invoiced (<code>QuotationInvoiceGuard</code>).</p><p><strong>Status:</strong> shipped with quotations <strong>1.4.0</strong>, contracts <strong>1.2.0</strong>, invoices <strong>1.6.0</strong>, estimates <strong>1.3.2</strong>.</p><h3 id="invoices-→-contacts-companies-quotations-optional" tabindex="-1">Invoices → Contacts / Companies / Quotations (optional) <a class="header-anchor" href="#invoices-→-contacts-companies-quotations-optional" aria-label="Permalink to &quot;Invoices → Contacts / Companies / Quotations (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invoices</span></span>
<span class="line"><span>  ├── may depend on Contacts     (optional — contact_id link)</span></span>
<span class="line"><span>  ├── may depend on Companies    (optional — company_id link)</span></span>
<span class="line"><span>  └── may depend on Quotations   (optional — quotation_id link)</span></span></code></pre></div><p>Invoices works as a licensed Billing module on its own catalog row with <strong>no required <code>module_dependencies</code> row</strong> — unlike Quotations/Contracts, it does not require Opportunities. Contact and Company links are optional and only surfaced/validated when that module is entitled. <code>quotation_id</code> is a plain tenant-scoped existence check (not gated by a <code>LinkableQuotation</code>-style entitlement rule, unlike the Contracts → Quotations link above).</p><p><strong>Status:</strong> <a href="/user-guide/invoices-overview">Invoices</a> is shipped.</p><h3 id="payments-→-invoices-required" tabindex="-1">Payments → Invoices (required) <a class="header-anchor" href="#payments-→-invoices-required" aria-label="Permalink to &quot;Payments → Invoices (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Payments</span></span>
<span class="line"><span>  └── depends on Invoices   (required)</span></span></code></pre></div><p>Payments records amounts against an invoice&#39;s <code>amount_paid</code> and allocates them to one or more <code>CustomerInvoice</code> rows on <strong>post</strong>, declaring Invoices as a <strong>required</strong> hard dependency (<code>module_dependencies</code>) — the first Phase 3 module to require another. Marketplace blocks installing Payments on a workspace that doesn&#39;t already have Invoices entitled.</p><p><strong>Status:</strong> <a href="/user-guide/payments-overview">Payments</a> is shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 3.</p><h3 id="resellers-→-payments-required" tabindex="-1">Resellers → Payments (required) <a class="header-anchor" href="#resellers-→-payments-required" aria-label="Permalink to &quot;Resellers → Payments (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Resellers</span></span>
<span class="line"><span>  └── depends on Payments   (required)</span></span></code></pre></div><p>Reseller commission accrues only when a linked customer invoice becomes fully <strong>Paid</strong> via the Payments ledger. Resellers declares Payments as a <strong>required</strong> hard dependency (<code>module_dependencies</code>). Marketplace blocks installing Resellers until Payments is entitled.</p><p><strong>Status:</strong> <a href="/user-guide/resellers-overview">Resellers</a> Phase 1 is shipped (free Sales opt-in). Cross-workspace reseller identity is deferred.</p><h3 id="reseller-payouts-→-resellers-required" tabindex="-1">Reseller Payouts → Resellers (required) <a class="header-anchor" href="#reseller-payouts-→-resellers-required" aria-label="Permalink to &quot;Reseller Payouts → Resellers (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reseller Payouts</span></span>
<span class="line"><span>  └── depends on Resellers   (required)</span></span></code></pre></div><p>The commission ledger (<code>reseller_commission_entries</code>) always references a <code>Reseller</code>. Reseller Payouts declares Resellers as a <strong>required</strong> hard dependency (<code>module_dependencies</code>). Install chain: Payments → Resellers → Reseller Payouts.</p><p><strong>Status:</strong> <a href="/user-guide/reseller-payouts-overview">Reseller Payouts</a> Phase 1 is shipped (free Sales opt-in).</p><h3 id="credit-notes-→-invoices-required" tabindex="-1">Credit Notes → Invoices (required) <a class="header-anchor" href="#credit-notes-→-invoices-required" aria-label="Permalink to &quot;Credit Notes → Invoices (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Credit Notes</span></span>
<span class="line"><span>  └── depends on Invoices   (required)</span></span></code></pre></div><p>Every <code>CustomerCreditNote</code> references a <code>CustomerInvoice</code> (<code>customer_invoice_id</code>, required). Credit Notes declares Invoices as a <strong>required</strong> hard dependency (<code>module_dependencies</code>), the same pattern as Payments → Invoices. Applying a credit note credits the linked invoice&#39;s <code>amount_credited</code> and recalculates <code>balance_due</code> (without changing invoice <code>status</code>). Marketplace blocks installing Credit Notes on a workspace that doesn&#39;t already have Invoices entitled.</p><p><strong>Status:</strong> <a href="/user-guide/credit-notes-overview">Credit Notes</a> is shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 3.</p><h3 id="estimates-→-invoices-required" tabindex="-1">Estimates → Invoices (required) <a class="header-anchor" href="#estimates-→-invoices-required" aria-label="Permalink to &quot;Estimates → Invoices (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Estimates</span></span>
<span class="line"><span>  └── depends on Invoices   (required)</span></span></code></pre></div><p><code>POST /estimates/{id}/convert</code> creates a <strong>draft</strong> <code>CustomerInvoice</code> from an accepted (or sent) estimate, copying its lines and linking it back via <code>customer_invoices.estimate_id</code>. Estimates declares Invoices as a <strong>required</strong> hard dependency (<code>module_dependencies</code>), the same pattern as Payments/Credit Notes → Invoices. Estimates also has optional soft links to Contacts, Companies, Opportunities, and Quotations (each validated only when entitled; no hard dependency rows). Marketplace blocks installing Estimates on a workspace that doesn&#39;t already have Invoices entitled.</p><p><strong>Status:</strong> <a href="/user-guide/estimates-overview">Estimates</a> is shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 3.</p><h3 id="purchase-orders-→-vendors-required" tabindex="-1">Purchase Orders → Vendors (required) <a class="header-anchor" href="#purchase-orders-→-vendors-required" aria-label="Permalink to &quot;Purchase Orders → Vendors (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Purchase Orders</span></span>
<span class="line"><span>  └── depends on Vendors   (required)</span></span></code></pre></div><p>A Purchase Order cannot exist without a supplier — every <code>PurchaseOrder</code> requires a <code>vendor_id</code>. Purchase Orders declares Vendors as a <strong>required</strong> hard dependency (<code>module_dependencies</code>), the same pattern as Payments → Invoices / Estimates → Invoices — Marketplace blocks installing Purchase Orders until Vendors is entitled.</p><p><strong>Status:</strong> <a href="/user-guide/vendors-overview">Vendors</a> and <a href="/user-guide/purchase-orders-overview">Purchase Orders</a> are both shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 4.</p><h3 id="expenses-→-vendors-purchase-orders-optional-shipped" tabindex="-1">Expenses → Vendors, Purchase Orders (optional, shipped) <a class="header-anchor" href="#expenses-→-vendors-purchase-orders-optional-shipped" aria-label="Permalink to &quot;Expenses → Vendors, Purchase Orders (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expenses</span></span>
<span class="line"><span>  ├── may depend on Vendors           (optional — unlocks vendor_id link)</span></span>
<span class="line"><span>  └── may depend on Purchase Orders   (optional — unlocks purchase_order_id link)</span></span></code></pre></div><p>Expenses installs standalone with <strong>no</strong> <code>module_dependencies</code> rows — it works as a generic expense record with no supplier or purchase order context. When Vendors is entitled, an Expense may optionally link <code>vendor_id</code>; when Purchase Orders is entitled, an Expense may optionally link <code>purchase_order_id</code>. Both links are validated only at the point of use (<code>LinkableVendor</code>, <code>LinkablePurchaseOrder</code> rules) — soft entitlement, no hard dependency rows, so Vendors/Purchase Orders can be uninstalled later without breaking Expenses (existing links are simply no longer enforced/displayed as active relations).</p><p><strong>Status:</strong> <a href="/user-guide/vendors-overview">Vendors</a>, <a href="/user-guide/purchase-orders-overview">Purchase Orders</a>, and <a href="/user-guide/expenses-overview">Expenses</a> are all shipped, completing Phase 4 — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 4.</p><h3 id="purchase-orders-→-expenses-optional-shipped-reverse-direction" tabindex="-1">Purchase Orders → Expenses (optional, shipped, reverse direction) <a class="header-anchor" href="#purchase-orders-→-expenses-optional-shipped-reverse-direction" aria-label="Permalink to &quot;Purchase Orders → Expenses (optional, shipped, reverse direction)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Purchase Orders</span></span>
<span class="line"><span>  └── may use Expenses   (optional — unlocks &quot;Convert to expense&quot; action)</span></span></code></pre></div><p><code>POST /purchase-orders/{id}/convert</code> creates a draft Expense from a <code>sent</code>/<code>partially_received</code>/<code>received</code> purchase order. This is a <strong>soft, call-time</strong> entitlement check inside <code>PurchaseOrderService::convertToExpense()</code> — not a <code>module_dependencies</code> row — so Purchase Orders keeps working with Expenses uninstalled; only the convert endpoint itself returns a 422 until Expenses is installed. The conversion is one-way and one-time (an existing <code>Expense</code> with that <code>purchase_order_id</code>, including soft-deleted, blocks re-conversion).</p><p><strong>Status:</strong> Shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 4 and <a href="/api/tenant-v1-purchase-orders#convert-to-expense-soft-dependency-on-expenses">Tenant Purchase Orders API</a>.</p><h3 id="leave-management-→-employees-required-shipped" tabindex="-1">Leave Management → Employees (required, shipped) <a class="header-anchor" href="#leave-management-→-employees-required-shipped" aria-label="Permalink to &quot;Leave Management → Employees (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leave Management</span></span>
<span class="line"><span>  └── depends on Employees   (required)</span></span></code></pre></div><p>Leave Management declares Employees as a required hard dependency (<code>module_dependencies</code>). Marketplace blocks installation until Employees is entitled. Leave balances and requests reference <code>employees.id</code>.</p><p><strong>Status:</strong> Shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 7.</p><h3 id="attendance-→-employees-required-shipped" tabindex="-1">Attendance → Employees (required, shipped) <a class="header-anchor" href="#attendance-→-employees-required-shipped" aria-label="Permalink to &quot;Attendance → Employees (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Attendance</span></span>
<span class="line"><span>  └── depends on Employees   (required)</span></span></code></pre></div><p>Attendance declares Employees as a required hard dependency. Daily records reference <code>employees.id</code>.</p><p><strong>Status:</strong> Shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 7.</p><h3 id="payroll-→-employees-required-shipped" tabindex="-1">Payroll → Employees (required, shipped) <a class="header-anchor" href="#payroll-→-employees-required-shipped" aria-label="Permalink to &quot;Payroll → Employees (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Payroll</span></span>
<span class="line"><span>  └── depends on Employees   (required)</span></span></code></pre></div><p>Payroll declares Employees as a required hard dependency. Payroll profiles and pay-run lines reference employee records; Payroll should not re-implement the employee directory.</p><p><strong>Status:</strong> Shipped — see <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 7.</p><h3 id="payroll-→-accounting-optional-shipped" tabindex="-1">Payroll → Accounting (optional, shipped) <a class="header-anchor" href="#payroll-→-accounting-optional-shipped" aria-label="Permalink to &quot;Payroll → Accounting (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Payroll</span></span>
<span class="line"><span>  └── may use Accounting   (optional — unlocks pay-run journal post)</span></span></code></pre></div><p>Payroll installs and runs without Accounting. <code>POST /pay-runs/{id}/post</code> is a soft, call-time entitlement check inside <code>PayRunService::postToJournal()</code> — also registered as an <strong>optional</strong> <code>module_dependencies</code> row — so Marketplace can surface the integration while Payroll remains usable alone. Posting creates a draft journal (expense debit / liability credit) and stores <code>journal_entry_id</code>.</p><p><strong>Status:</strong> Shipped — see <a href="/api/tenant-v1-payroll#post-pay-runspayrunpost">Tenant Payroll API</a>.</p><h3 id="payments-→-accounting-optional-shipped" tabindex="-1">Payments → Accounting (optional, shipped) <a class="header-anchor" href="#payments-→-accounting-optional-shipped" aria-label="Permalink to &quot;Payments → Accounting (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Payments</span></span>
<span class="line"><span>  └── may use Accounting   (optional — deposit account + auto-posted journal on payment post)</span></span></code></pre></div><p>Payments installs without Accounting (still requires Invoices). When Accounting is entitled, payment post creates a posted journal (Dr cash/bank deposit / Cr AR) via <code>CashMovementJournalService</code> and stores <code>deposit_account_id</code> + <code>journal_entry_id</code>. Void voids the linked journal. Optional <code>module_dependencies</code> row.</p><h3 id="expenses-→-accounting-optional-shipped" tabindex="-1">Expenses → Accounting (optional, shipped) <a class="header-anchor" href="#expenses-→-accounting-optional-shipped" aria-label="Permalink to &quot;Expenses → Accounting (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expenses</span></span>
<span class="line"><span>  └── may use Accounting   (optional — paid-from account + auto-posted journal on mark paid)</span></span></code></pre></div><p>Expenses installs standalone. When Accounting is entitled, <code>POST /expenses/{id}/pay</code> requires <code>paid_from_account_id</code> (cash/bank) and posts Dr expense / Cr paid-from for amount+tax. Optional <code>module_dependencies</code> row.</p><h3 id="help-desk-→-contacts-companies-optional-shipped" tabindex="-1">Help Desk → Contacts, Companies (optional, shipped) <a class="header-anchor" href="#help-desk-→-contacts-companies-optional-shipped" aria-label="Permalink to &quot;Help Desk → Contacts, Companies (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help Desk</span></span>
<span class="line"><span>  ├── may depend on Contacts   (optional — unlocks contact_id link)</span></span>
<span class="line"><span>  └── may depend on Companies  (optional — unlocks company_id link)</span></span></code></pre></div><p>Help Desk installs standalone with <strong>no</strong> <code>module_dependencies</code> rows — it works as an internal ticket queue with no CRM context. When Contacts is entitled, a ticket may optionally link <code>contact_id</code>; when Companies is entitled, a ticket may optionally link <code>company_id</code>. Both links are validated only at the point of use (<code>LinkableContact</code>, <code>LinkableCompany</code> rules) — soft entitlement, no hard dependency rows.</p><p><strong>Status:</strong> Shipped — see <a href="/user-guide/help-desk-overview">Help Desk Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 8.</p><h3 id="whatsapp-cloud-→-leads-optional-shipped" tabindex="-1">WhatsApp Cloud → Leads (optional, shipped) <a class="header-anchor" href="#whatsapp-cloud-→-leads-optional-shipped" aria-label="Permalink to &quot;WhatsApp Cloud → Leads (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WhatsApp Cloud</span></span>
<span class="line"><span>  └── may depend on Leads   (optional — unlocks lead_id link + timeline mirrors)</span></span></code></pre></div><p>WhatsApp Cloud installs standalone with <strong>no</strong> <code>module_dependencies</code> rows. Conversations work with <code>lead_id</code> null. When Leads is entitled, agents may link a Lead and outbound/inbound messages mirror onto the Lead timeline via <code>LeadService::recordActivity</code>. Communication Templates (<code>wa.me</code>) remains a separate free module and is not a hard dependency.</p><p><strong>Status:</strong> Shipped MVP <strong>1.0.0</strong> — see <a href="/user-guide/whatsapp-cloud-overview">WhatsApp Cloud Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a> Phase 1.</p><h3 id="inventory-→-products-required-shipped" tabindex="-1">Inventory → Products (required, shipped) <a class="header-anchor" href="#inventory-→-products-required-shipped" aria-label="Permalink to &quot;Inventory → Products (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inventory</span></span>
<span class="line"><span>  └── depends on Products   (required)</span></span></code></pre></div><p>Inventory declares Products as a required hard dependency (<code>module_dependencies</code>), so Marketplace blocks Inventory installation until Products is entitled. Stock levels, adjustments, transfers, and receipt posting all reference Products.</p><h3 id="inventory-→-warehouses-optional-shipped" tabindex="-1">Inventory → Warehouses (optional, shipped) <a class="header-anchor" href="#inventory-→-warehouses-optional-shipped" aria-label="Permalink to &quot;Inventory → Warehouses (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inventory</span></span>
<span class="line"><span>  └── may use Warehouses   (optional — locations and default warehouse)</span></span></code></pre></div><p>Inventory soft-uses Warehouses through <code>WarehouseService::ensureDefaultWarehouse()</code> to provide the <code>MAIN</code> location when a stock action omits <code>warehouse_id</code>. The Warehouses module gates its own management UI and CRUD; it is not a hard Inventory install dependency.</p><h3 id="purchase-orders-→-inventory-optional-shipped" tabindex="-1">Purchase Orders → Inventory (optional, shipped) <a class="header-anchor" href="#purchase-orders-→-inventory-optional-shipped" aria-label="Permalink to &quot;Purchase Orders → Inventory (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Purchase Orders</span></span>
<span class="line"><span>  └── may use Inventory   (optional — receipt stock posting)</span></span></code></pre></div><p>Purchase Orders continues to work without Inventory. When Inventory and Products are entitled, receiving a PO posts stock-in for each line with a nullable <code>product_id</code> whose linked Product tracks stock; <code>LinkableProduct</code> validates that link. Partially received remains acknowledgement-only. This is a soft integration, not a <code>module_dependencies</code> row.</p><h3 id="financial-reports-→-accounting-required-shipped" tabindex="-1">Financial Reports → Accounting (required, shipped) <a class="header-anchor" href="#financial-reports-→-accounting-required-shipped" aria-label="Permalink to &quot;Financial Reports → Accounting (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Financial Reports</span></span>
<span class="line"><span>  └── depends on Accounting   (required)</span></span></code></pre></div><p>Financial Reports declares Accounting as a required hard dependency (<code>module_dependencies</code>). Marketplace blocks installation until Accounting is entitled. Reports read posted journal lines only.</p><h3 id="accounting-→-inventory-optional-future" tabindex="-1">Accounting → Inventory (optional, future) <a class="header-anchor" href="#accounting-→-inventory-optional-future" aria-label="Permalink to &quot;Accounting → Inventory (optional, future)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accounting</span></span>
<span class="line"><span>  └── may depend on Inventory   (optional)</span></span></code></pre></div><p>Accounting ships standalone (manual double-entry) plus soft cash movements from Payments/Expenses and Finance → Transfers. A future milestone may optionally integrate stock valuations or COGS-related flows through contracts/services. Auto-posting from Invoices / Credit Notes / Purchase Orders / Inventory remains deferred.</p><h3 id="projects-standalone-tasks-→-projects-optional-shipped" tabindex="-1">Projects (standalone) + Tasks → Projects (optional, shipped) <a class="header-anchor" href="#projects-standalone-tasks-→-projects-optional-shipped" aria-label="Permalink to &quot;Projects (standalone) + Tasks → Projects (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Projects</span></span>
<span class="line"><span>  ├── may depend on Contacts       (optional — contact_id link)</span></span>
<span class="line"><span>  ├── may depend on Companies      (optional — company_id link)</span></span>
<span class="line"><span>  └── may depend on Opportunities  (optional — opportunity_id link)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tasks</span></span>
<span class="line"><span>  └── may depend on Projects       (optional — project_id link)</span></span></code></pre></div><p>Projects installs standalone with <strong>no</strong> <code>module_dependencies</code> rows — title, status board, assignee/members, notes/timeline work without CRM modules. Soft FKs to Contact / Company / Opportunity are validated only when those modules are entitled. Tasks may optionally set <code>project_id</code> via <code>LinkableProject</code> (Projects entitled + project visible to the actor); uninstalling Projects nulls the FK (<code>nullOnDelete</code>). No hard install dependency either direction.</p><p><strong>Status:</strong> <a href="/user-guide/projects-overview">Projects</a> shipped lean <strong>v1.0.0</strong>; Tasks catalog <strong>1.2.0</strong> adds soft <code>project_id</code>.</p><h3 id="knowledge-base-standalone-shipped" tabindex="-1">Knowledge Base (standalone, shipped) <a class="header-anchor" href="#knowledge-base-standalone-shipped" aria-label="Permalink to &quot;Knowledge Base (standalone, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Knowledge Base</span></span>
<span class="line"><span>  └── (no hard dependencies)</span></span></code></pre></div><p>Knowledge Base installs as a free Operations Marketplace opt-in (<code>knowledge-base</code> <strong>1.0.0</strong>) with <strong>no</strong> <code>module_dependencies</code> rows. Internal workspace articles only — Help Desk links, public URLs, and Automation triggers are deferred and must remain soft/optional if added later.</p><p><strong>Status:</strong> Shipped — see <a href="/user-guide/knowledge-base-overview">Knowledge Base Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><h3 id="assets-standalone-shipped" tabindex="-1">Assets (standalone, shipped) <a class="header-anchor" href="#assets-standalone-shipped" aria-label="Permalink to &quot;Assets (standalone, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assets</span></span>
<span class="line"><span>  ├── may link Vendor                 (soft, when Vendors entitled)</span></span>
<span class="line"><span>  └── may link Employee               (soft, when Employees entitled)</span></span></code></pre></div><p>Assets installs as a free Operations Marketplace opt-in (<code>assets</code> <strong>1.0.0</strong>) with <strong>no</strong> <code>module_dependencies</code> rows. The register works alone (name, number, status, category, location, purchase/warranty, assignee, notes/timeline). Optional <code>vendor_id</code> / <code>employee_id</code> are validated only at the point of use (<code>LinkableVendor</code>, <code>LinkableEmployee</code>) — soft entitlement, no hard install dependency. Location is free-text in v1 (no Warehouse FK). Depreciation / Accounting, Products / Inventory coupling, and Help Desk maintenance tickets are deferred.</p><p><strong>Status:</strong> Shipped — see <a href="/user-guide/assets-overview">Assets Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><h3 id="documents-→-storage-required-shipped" tabindex="-1">Documents → Storage (required, shipped) <a class="header-anchor" href="#documents-→-storage-required-shipped" aria-label="Permalink to &quot;Documents → Storage (required, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Documents</span></span>
<span class="line"><span>  └── depends on Storage   (required)</span></span></code></pre></div><p>Documents installs as a free Operations Marketplace opt-in (<code>documents</code> <strong>1.0.0</strong>) with a <strong>hard</strong> <code>module_dependencies</code> row on free <strong>Storage</strong>. Install is blocked until Storage is entitled. Uploaded file bytes (<code>documents.size_bytes</code>) count toward workspace Storage used quota; soft-deleted documents are excluded until restored. Flat categories only — soft links to other modules and nested folders are deferred and must remain soft/optional if added later.</p><p><strong>Status:</strong> Shipped — see <a href="/user-guide/documents-overview">Documents Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><h3 id="analytics-reports-→-crm-sales-billing-purchasing-modules-optional-shipped" tabindex="-1">Analytics / Reports → CRM / Sales / Billing / Purchasing modules (optional, shipped) <a class="header-anchor" href="#analytics-reports-→-crm-sales-billing-purchasing-modules-optional-shipped" aria-label="Permalink to &quot;Analytics / Reports → CRM / Sales / Billing / Purchasing modules (optional, shipped)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reports (slug analytics)</span></span>
<span class="line"><span>  ├── may use Leads / Tasks              (CRM report + overview)</span></span>
<span class="line"><span>  ├── may use Opportunities / Quotations / Contracts (Sales report)</span></span>
<span class="line"><span>  ├── may use Invoices / Payments / Credit Notes (Billing report)</span></span>
<span class="line"><span>  ├── may use Vendors / Purchase Orders / Expenses (Purchasing report)</span></span>
<span class="line"><span>  └── may use Help Desk / Projects       (overview sections)</span></span></code></pre></div><p>Reports installs as a free Operations Marketplace opt-in (<code>analytics</code> <strong>1.1.0</strong>, display name Reports) with <strong>no</strong> <code>module_dependencies</code> rows. Overview sections and domain reports include data only when that source module is entitled <strong>and</strong> the actor has <code>{module}.view</code>. Accounting statements stay in Financial Reports.</p><p><strong>Status:</strong> Shipped — see <a href="/user-guide/analytics-overview">Analytics Overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><h3 id="ai-→-domain-modules-optional" tabindex="-1">AI → domain modules (optional) <a class="header-anchor" href="#ai-→-domain-modules-optional" aria-label="Permalink to &quot;AI → domain modules (optional)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI</span></span>
<span class="line"><span>  ├── may optionally integrate with Leads</span></span>
<span class="line"><span>  ├── may optionally integrate with Tasks</span></span>
<span class="line"><span>  ├── may optionally integrate with CRM (Contacts, Companies, …)</span></span>
<span class="line"><span>  └── … other domain modules as needed</span></span></code></pre></div><p>AI Integration is planned as a cross-cutting capability. Integrations with Leads, Tasks, CRM, and similar modules should be <strong>optional</strong> — AI must not require every domain module to be installed.</p><h3 id="storage-packs-→-storage-required" tabindex="-1">Storage packs → Storage (required) <a class="header-anchor" href="#storage-packs-→-storage-required" aria-label="Permalink to &quot;Storage packs → Storage (required)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>storage-10 / storage-50 / storage-100 / storage-500 / storage-1000</span></span>
<span class="line"><span>  └── depends on storage   (required)</span></span></code></pre></div><p>Billable capacity packs cannot install until free <strong>Storage</strong> is entitled. Packs are mutually exclusive in product logic (cancel current pack before buying another size). Content upload surfaces (Team Chat, Feedback, Lead imports) soft-check Storage allowance; they do not declare a hard <code>module_dependencies</code> row on Storage. <strong>Documents</strong> is different: it declares a <strong>required</strong> dependency on Storage. Team Chat soft-companion installs free Storage when Team Chat is activated.</p><p><strong>Status:</strong> <a href="/user-guide/storage-overview">Storage</a> shipped.</p><h2 id="design-rules" tabindex="-1">Design rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to &quot;Design rules&quot;">​</a></h2><p>When designing a new module:</p><ol><li>List <strong>required</strong> dependencies explicitly in the module’s documentation.</li><li>List <strong>optional</strong> integrations separately so install and licensing expectations stay clear.</li><li>Keep business logic inside the owning module; call dependents through contracts/services only (<a href="./module-architecture">Module Architecture</a>).</li><li>Do not assume a dependency is always present unless it is marked <strong>required</strong> and the platform later enforces that rule.</li><li>Do not implement dependency resolution in application code based on this document alone — that remains future work.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./module-architecture">Module Architecture</a></li><li><a href="./module-licensing">Module Licensing</a></li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> (Calendar, Meetings, AI)</li><li><a href="/developer-guide/entitlements">Entitlements</a></li></ul>`,158)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
